'use client';

import { createContext, FormEvent, useContext, useEffect, useState } from 'react';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { apiRequest, setAccessToken } from '../lib/api';
import { todayInHotelTimezone } from '../lib/hotel-date-time';
import { useDialog } from './ReactDialog';
import { ReservationPaymentSchedule, type PaymentSchedule } from './ReservationPaymentSchedule';

let refreshInFlight: Promise<string> | null = null;
let staffSessionCheckedAt = 0;
const STAFF_SESSION_CACHE_MS = 5 * 60 * 1000;

export type AdminProfile = { id: string; name: string; email: string; role: string; staffHotelId?: string | null; staffDepartment?: string | null; jobTitle?: string | null; staffHotel?: { id: string; name: string } | null };
const AdminProfileContext = createContext<{ profile: AdminProfile | null; loading: boolean }>({ profile: null, loading: true });

export function useAdminProfile() { return useContext(AdminProfileContext); }

function refreshStaffSession() {
  if (staffSessionCheckedAt && Date.now() - staffSessionCheckedAt < STAFF_SESSION_CACHE_MS) {
    return Promise.resolve('cached-staff-session');
  }
  if (!refreshInFlight) {
    refreshInFlight = apiRequest<{ accessToken: string; user: { role: string } }>('/auth/refresh', { method: 'POST' })
      .then((body) => { if (body.user.role === 'AGENT') throw new Error('AGENT_SESSION'); if (body.user.role === 'SERVICE_STAFF') throw new Error('SERVICE_STAFF_SESSION'); setAccessToken(body.accessToken, body.user.role); staffSessionCheckedAt = Date.now(); return body.accessToken; })
      .catch((reason) => { staffSessionCheckedAt = 0; throw reason; })
      .finally(() => { refreshInFlight = null; });
  }
  return refreshInFlight;
}

export function invalidateStaffSession() { staffSessionCheckedAt = 0; }

export function AdminAuthGate({ children }: { children: React.ReactNode }) {
  const [ready, setReady] = useState(false);
  const [profile, setProfile] = useState<AdminProfile | null>(null);
  useEffect(() => {
    refreshStaffSession().then(() => apiRequest<{ user: AdminProfile }>('/auth/me')).then((body) => { setProfile(body.user); setReady(true); }).catch((reason) => { setAccessToken(null); const next = `${window.location.pathname}${window.location.search}`; window.location.href = reason instanceof Error && reason.message === 'AGENT_SESSION' ? `${process.env.NEXT_PUBLIC_BASE_PATH ?? ''}/agent` : reason instanceof Error && reason.message === 'SERVICE_STAFF_SESSION' ? `${process.env.NEXT_PUBLIC_BASE_PATH ?? ''}/staff` : `${process.env.NEXT_PUBLIC_BASE_PATH ?? ''}/login?next=${encodeURIComponent(next)}`; });
  }, []);
  if (!ready) return <main className="page"><p className="loading">Checking staff session - </p></main>;
  return <AdminProfileContext.Provider value={{ profile, loading: false }}>{children}</AdminProfileContext.Provider>;
}

function useData<T>(path: string, reloadKey = 0) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState('');
  useEffect(() => { apiRequest<T>(path).then(setData).catch((reason: Error) => setError(reason.message)); }, [path, reloadKey]);
  return { data, error };
}

export function DashboardData() {
  const { data, error } = useData<{ bookings: number; balancePending: number; pendingSync: number; failedJobs: number; revenue: number }>('/reports/dashboard');
  if (error) return <p className="error">{error}</p>;
  if (!data) return <p className="loading">Loading dashboard - </p>;
  return <><div className="metrics"><div><b>{data.bookings}</b><span>Bookings</span></div><div><b>INR {data.balancePending.toFixed(2)}</b><span>Balance pending</span></div><div><b>{data.pendingSync}</b><span>Sync attention</span></div><div><b>{data.failedJobs}</b><span>Failed jobs</span></div></div><section className="panel"><h2>Revenue</h2><p className="metric">INR {data.revenue.toFixed(2)}</p></section></>;
}

type ReservationRow = { reference: string; guestName: string; email?: string; mobile?: string; checkIn: string; checkOut: string; source: string; status: string; balanceAmount: number | string };
type ReservationList = { items: ReservationRow[]; pagination: { page: number; limit: number; total: number; pages: number } };
type ReservationHotel = { id: string; name: string; rooms: { id: string; name: string; ratePlans: { id: string; name: string; mealPlan: string }[] }[] };
type ReservationDetail = { reference: string; status: string; paymentStatus: string; syncStatus: string; guestName: string; email: string; mobile: string; address?: string | null; gstin?: string | null; source: string; sourceName?: string | null; checkIn: string; checkOut: string; totalAmount: number | string; taxAmount: number | string; advanceAmount: number | string; balanceAmount: number | string; specialRequest?: string | null; billingInstruction?: string | null; internalRemark?: string | null; hotel: { name: string }; lines: { roomType: { name: string }; ratePlan: { name: string }; checkIn: string; checkOut: string; rooms: number; adults: number; children: number; nightlyRate: number | string; taxAmount: number | string; lineTotal: number | string }[]; payments: { amount: number | string; mode: string; verified: boolean; reference?: string | null }[]; paymentSchedule?: PaymentSchedule | null };
type ReservationForm = { hotelId: string; roomTypeId: string; ratePlanId: string; guestName: string; email: string; mobile: string; address: string; gstin: string; checkIn: string; checkOut: string; rooms: number; adults: number; children: number; source: string; sourceName: string; specialRequest: string; billingInstruction: string; internalRemark: string };
const blankReservation: ReservationForm = { hotelId: '', roomTypeId: '', ratePlanId: '', guestName: '', email: '', mobile: '', address: '', gstin: '', checkIn: '', checkOut: '', rooms: 1, adults: 2, children: 0, source: 'DIRECT', sourceName: '', specialRequest: '', billingInstruction: '', internalRemark: '' };
type ReservationQuote = { key: string; token: string; expiresAt: string; quotedTotal: number | string; quotedTax?: number | string; quotedBreakdown?: unknown; lines?: unknown[] };

function reservationQuoteKey(form: ReservationForm) {
  return [form.hotelId, form.roomTypeId, form.ratePlanId, form.checkIn, form.checkOut, form.rooms, form.adults, form.children].join('|');
}

type ReservationCreateViewProps = {
  form: ReservationForm;
  hotels: ReservationHotel[];
  selectedHotel?: ReservationHotel;
  selectedRoom?: ReservationHotel['rooms'][number];
  plans: ReservationHotel['rooms'][number]['ratePlans'];
  quote: ReservationQuote | null;
  busy: boolean;
  formError: string;
  onChange: (patch: Partial<ReservationForm>) => void;
  onCheckAvailability: () => void;
  onSubmit: (event: FormEvent) => void;
  onClose: () => void;
};

function ReservationCreateView({ form, hotels, selectedHotel, selectedRoom, plans, quote, busy, formError, onChange, onCheckAvailability, onSubmit, onClose }: ReservationCreateViewProps) {
  const quoteExpired = quote ? new Date(quote.expiresAt).getTime() <= Date.now() : false;
  const hasValidQuote = Boolean(quote && !quoteExpired);
  return <form className="formCard reservationForm" onSubmit={onSubmit}>
    <div className="rangeSectionHeader"><h2>Add reservation</h2><button className="smallBtn" type="button" onClick={onClose}>Close</button></div>
    <h3>Guest details</h3>
    <div className="two"><label>Guest name<input value={form.guestName} onChange={(e) => onChange({ guestName: e.target.value })} required /></label><label>Email<input type="email" value={form.email} onChange={(e) => onChange({ email: e.target.value })} required /></label></div>
    <div className="two"><label>Mobile<input value={form.mobile} onChange={(e) => onChange({ mobile: e.target.value })} required /></label><label>GSTIN<input value={form.gstin} onChange={(e) => onChange({ gstin: e.target.value })} /></label></div>
    <label>Address<textarea rows={2} value={form.address} onChange={(e) => onChange({ address: e.target.value })} /></label>
    <h3>Booking details</h3>
    <div className="two"><label>Source<select value={form.source} onChange={(e) => onChange({ source: e.target.value, sourceName: '' })}><option>DIRECT</option><option>WEBSITE</option><option>PHONE</option><option>EMAIL</option><option>WHATSAPP</option><option>WALK_IN</option><option>AGENT</option><option>COMPANY</option><option>OTA</option></select></label>{['AGENT', 'COMPANY', 'OTA'].includes(form.source) && <label>{form.source === 'AGENT' ? 'Agent name' : form.source === 'COMPANY' ? 'Company name' : 'OTA name'}<input value={form.sourceName} onChange={(e) => onChange({ sourceName: e.target.value })} required /></label>}</div>
    <div className="two"><label>Hotel<select value={form.hotelId} onChange={(e) => onChange({ hotelId: e.target.value, roomTypeId: '', ratePlanId: '' })} required><option value="">Select hotel</option>{hotels.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Room<select value={form.roomTypeId} onChange={(e) => onChange({ roomTypeId: e.target.value, ratePlanId: '' })} required><option value="">Select room</option>{selectedHotel?.rooms.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div>
    <div className="two"><label>Rate plan<select value={form.ratePlanId} onChange={(e) => onChange({ ratePlanId: e.target.value })} required><option value="">Select rate plan</option>{plans.map((item) => <option key={item.id} value={item.id}>{item.name} - {item.mealPlan}</option>)}</select></label><label>Check-in<input type="date" value={form.checkIn} onChange={(e) => onChange({ checkIn: e.target.value })} required /></label></div>
    <div className="three"><label>Check-out<input type="date" value={form.checkOut} onChange={(e) => onChange({ checkOut: e.target.value })} required /></label><label>Rooms<input type="number" min="1" value={form.rooms} onChange={(e) => onChange({ rooms: Number(e.target.value) })} /></label><label>Adults<input type="number" min="1" value={form.adults} onChange={(e) => onChange({ adults: Number(e.target.value) })} /></label></div>
    <label>Children<input type="number" min="0" value={form.children} onChange={(e) => onChange({ children: Number(e.target.value) })} /></label>
    <section className="reservationQuotePanel panel" aria-live="polite" aria-label="Authoritative reservation quote"><h3>Availability and price</h3>{quote && hasValidQuote ? <div className="reservationQuoteResult"><p className="success">Quote and hold confirmed until {new Date(quote.expiresAt).toLocaleString()}.</p><div className="reviewGrid"><div><span>Hotel</span><b>{selectedHotel?.name || 'Selected hotel'}</b></div><div><span>Room and rate</span><b>{selectedRoom?.name || 'Selected room'} / {plans.find((item) => item.id === form.ratePlanId)?.name || 'Selected rate plan'}</b></div><div><span>Stay</span><b>{form.checkIn} to {form.checkOut}</b></div>{quote.quotedTax !== undefined && <div><span>Tax</span><b>INR {Number(quote.quotedTax).toFixed(2)}</b></div>}<div><span>Quoted total</span><b>INR {Number(quote.quotedTotal).toFixed(2)}</b></div></div></div> : <p className="mutedText">Check server availability and price before creating this reservation. Guest details do not invalidate a valid quote.</p>}<button className="smallBtn" type="button" onClick={onCheckAvailability} disabled={busy}>{busy ? 'Checking...' : quote ? 'Recheck availability and price' : 'Check Availability & Price'}</button></section>
    <section className="reservationCreateSummary" aria-label="Reservation summary"><h3>Reservation summary</h3><div><span>Hotel / room</span><b>{selectedHotel?.name || 'Select a hotel'} / {selectedRoom?.name || 'Select a room'}</b></div><div><span>Rate plan</span><b>{plans.find((item) => item.id === form.ratePlanId)?.name || 'Select a rate plan'}</b></div><div><span>Stay</span><b>{form.checkIn || 'Check-in'} to {form.checkOut || 'check-out'} · {form.rooms} room(s) · {form.adults} adult(s) · {form.children} child(ren)</b></div></section>
    <h3>Instructions and requests</h3><details className="reservationAdvancedFields"><summary>Additional instructions (optional)</summary><label>Special request<textarea rows={2} value={form.specialRequest} onChange={(e) => onChange({ specialRequest: e.target.value })} /></label><label>Billing instructions<textarea rows={2} value={form.billingInstruction} onChange={(e) => onChange({ billingInstruction: e.target.value })} /></label><label>Internal remark<textarea rows={2} value={form.internalRemark} onChange={(e) => onChange({ internalRemark: e.target.value })} /></label></details>
    {formError && <p className="error" role="alert">{formError}</p>}<button className="btn" disabled={busy || !hasValidQuote}>{busy ? 'Saving...' : 'Create reservation'}</button>
  </form>;
}

export function ReservationData() {
  const dialog = useDialog();
  const searchParams = useSearchParams();
  const [page, setPage] = useState(() => Math.max(1, Number(searchParams.get('page') ?? 1) || 1)); const [search, setSearch] = useState(() => searchParams.get('search') ?? ''); const [status, setStatus] = useState(() => searchParams.get('status') ?? ''); const [reload, setReload] = useState(0);
  useEffect(() => { setPage(Math.max(1, Number(searchParams.get('page') ?? 1) || 1)); setSearch(searchParams.get('search') ?? ''); setStatus(searchParams.get('status') ?? ''); }, [searchParams]);
  const reservationQuery = new URLSearchParams({ page: String(page), limit: '25', ...(search.trim() ? { search: search.trim() } : {}), ...(status ? { status } : {}), ...(searchParams.get('hotelId') ? { hotelId: searchParams.get('hotelId')! } : {}), ...(searchParams.get('from') ? { from: searchParams.get('from')! } : {}), ...(searchParams.get('to') ? { to: searchParams.get('to')! } : {}) }).toString();
  const { data, error } = useData<ReservationList>(`/reservations?${reservationQuery}`, reload);
  const { data: hotels, error: hotelError } = useData<ReservationHotel[]>('/hotels');
  const [form, setForm] = useState<ReservationForm>(blankReservation); const [detail, setDetail] = useState<ReservationDetail | null>(null); const [editReference, setEditReference] = useState(''); const [showForm, setShowForm] = useState(false); const [busy, setBusy] = useState(false); const [formError, setFormError] = useState(''); const [quote, setQuote] = useState<ReservationQuote | null>(null);
  const selectedHotel = hotels?.find((item) => item.id === form.hotelId); const selectedRoom = selectedHotel?.rooms.find((item) => item.id === form.roomTypeId); const plans = selectedRoom?.ratePlans ?? [];
  useEffect(() => { if (hotels?.[0] && !form.hotelId && !editReference) setForm((current) => ({ ...current, hotelId: hotels[0].id })); }, [hotels, form.hotelId, editReference]);
  useEffect(() => { if (searchParams.get('create') === '1' && hotels?.length && !showForm && !editReference) startCreate(); }, [hotels, searchParams, showForm, editReference]);
  useEffect(() => { if (selectedHotel && !selectedHotel.rooms.some((item) => item.id === form.roomTypeId)) setForm((current) => ({ ...current, roomTypeId: selectedHotel.rooms[0]?.id ?? '', ratePlanId: '' })); }, [selectedHotel, form.roomTypeId]);
  useEffect(() => { if (selectedRoom && !plans.some((item) => item.id === form.ratePlanId)) setForm((current) => ({ ...current, ratePlanId: plans[0]?.id ?? '' })); }, [selectedRoom, plans, form.ratePlanId]);
  function startCreate() { setDetail(null); setEditReference(''); setForm({ ...blankReservation, hotelId: hotels?.[0]?.id ?? '' }); setQuote(null); setFormError(''); setShowForm(true); }
  async function startEditByReference(reference: string) { setBusy(true); setFormError(''); try { const loaded = await apiRequest<ReservationDetail>(`/reservations/${encodeURIComponent(reference)}/detail`); setDetail(loaded); setEditReference(reference); setQuote(null); setForm({ ...blankReservation, guestName: loaded.guestName, email: loaded.email, mobile: loaded.mobile, address: loaded.address ?? '', gstin: loaded.gstin ?? '', source: loaded.source, sourceName: loaded.sourceName ?? '', checkIn: loaded.checkIn.slice(0, 10), checkOut: loaded.checkOut.slice(0, 10), specialRequest: loaded.specialRequest ?? '', billingInstruction: loaded.billingInstruction ?? '', internalRemark: loaded.internalRemark ?? '' }); setShowForm(true); } catch (reason) { setFormError(reason instanceof Error ? reason.message : 'Could not load reservation details'); } finally { setBusy(false); } }
  async function startEdit(row: ReservationRow) { return startEditByReference(row.reference); }
  useEffect(() => {
    if (!data || showForm || editReference) return;
    const requested = searchParams.get('open');
    if (requested) { void startEditByReference(requested); return; }
    const searched = searchParams.get('search') && data.items.length === 1 && data.items[0].reference === searchParams.get('search') ? searchParams.get('search') : null;
    if (searched) void startEditByReference(searched);
  }, [data, editReference, searchParams, showForm]);
  const currentQuoteKey = reservationQuoteKey(form);
  useEffect(() => {
    if (editReference || !quote || quote.key === currentQuoteKey) return;
    setQuote(null);
    setFormError('Booking details changed. Recheck availability and price.');
  }, [currentQuoteKey, editReference, quote]);
  async function checkAvailability() {
    const effectiveHotelId = form.hotelId || hotels?.[0]?.id || '';
    const effectiveRoomTypeId = form.roomTypeId || hotels?.find((item) => item.id === effectiveHotelId)?.rooms[0]?.id || '';
    const effectiveRatePlanId = form.ratePlanId || hotels?.find((item) => item.id === effectiveHotelId)?.rooms.find((item) => item.id === effectiveRoomTypeId)?.ratePlans[0]?.id || '';
    const missingReservationFields = [['hotel', effectiveHotelId], ['room', effectiveRoomTypeId], ['rate plan', effectiveRatePlanId], ['check-in date', form.checkIn], ['check-out date', form.checkOut]].filter(([, value]) => !value).map(([label]) => label);
    if (missingReservationFields.length) { setFormError(`Select ${missingReservationFields.join(', ')}.`); return; }
    const effectiveForm = { ...form, hotelId: effectiveHotelId, roomTypeId: effectiveRoomTypeId, ratePlanId: effectiveRatePlanId };
    setForm(effectiveForm);
    setBusy(true); setFormError(''); setQuote(null);
    try {
      const hold = await apiRequest<ReservationQuote>('/holds', { method: 'POST', body: JSON.stringify({ hotelId: effectiveHotelId, roomTypeId: effectiveRoomTypeId, ratePlanId: effectiveRatePlanId, checkIn: form.checkIn, checkOut: form.checkOut, rooms: Number(form.rooms), adults: Number(form.adults), children: Number(form.children), guestEmail: form.email }) });
      setQuote({ ...hold, key: reservationQuoteKey(effectiveForm) });
    } catch (reason) { setFormError(reason instanceof Error ? reason.message : 'Could not check availability and price'); }
    finally { setBusy(false); }
  }
  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setFormError('');
    try {
      if (editReference) {
        await apiRequest(`/reservations/${encodeURIComponent(editReference)}`, { method: 'PATCH', body: JSON.stringify({ type: 'GUEST_DETAILS', idempotencyKey: `admin-ui:${editReference}:${crypto.randomUUID()}`, guestName: form.guestName, email: form.email, mobile: form.mobile, address: form.address, gstin: form.gstin, source: form.source, sourceName: form.sourceName, specialRequest: form.specialRequest, billingInstruction: form.billingInstruction, internalRemark: form.internalRemark }) });
      } else {
        if (!quote || quote.key !== currentQuoteKey) throw new Error('Check availability and price before creating the reservation.');
        if (new Date(quote.expiresAt).getTime() <= Date.now()) { setQuote(null); throw new Error('Quote expired. Recheck availability.'); }
        const effectiveHotelId = form.hotelId || hotels?.[0]?.id || '';
        const effectiveRoomTypeId = form.roomTypeId || hotels?.find((item) => item.id === effectiveHotelId)?.rooms[0]?.id || '';
        const effectiveRatePlanId = form.ratePlanId || hotels?.find((item) => item.id === effectiveHotelId)?.rooms.find((item) => item.id === effectiveRoomTypeId)?.ratePlans[0]?.id || '';
        const missingReservationFields = [['hotel', effectiveHotelId], ['room', effectiveRoomTypeId], ['rate plan', effectiveRatePlanId], ['check-in date', form.checkIn], ['check-out date', form.checkOut]].filter(([, value]) => !value).map(([label]) => label);
        if (missingReservationFields.length) throw new Error(`Select ${missingReservationFields.join(', ')}.`);
        await apiRequest('/reservations/manual', { method: 'POST', body: JSON.stringify({ holdToken: quote.token, guestName: form.guestName, email: form.email, mobile: form.mobile, address: form.address, gstin: form.gstin, source: form.source, sourceName: form.sourceName || 'Admin UI', specialRequest: form.specialRequest, billingInstruction: form.billingInstruction, internalRemark: form.internalRemark }) });
      }
      setShowForm(false); setDetail(null); setEditReference(''); setQuote(null); setReload((value) => value + 1);
    } catch (reason) { setFormError(reason instanceof Error ? reason.message : 'Could not save reservation'); } finally { setBusy(false); }
  }
  function updateForm(patch: Partial<ReservationForm>) { setForm((current) => ({ ...current, ...patch })); }
  async function cancel(row: ReservationRow) { const reason = await dialog.prompt({ title: 'Cancel reservation', label: `Cancellation reason for ${row.reference}`, placeholder: 'Enter cancellation reason', confirmLabel: 'Cancel Reservation' }); if (!reason?.trim()) return; setBusy(true); try { await apiRequest(`/reservations/${encodeURIComponent(row.reference)}/cancel`, { method: 'POST', body: JSON.stringify({ reason }) }); setReload((value) => value + 1); } catch (caught) { setFormError(caught instanceof Error ? caught.message : 'Could not cancel reservation'); } finally { setBusy(false); } }
  if (error || hotelError) return <p className="error" role="alert">{error || hotelError}</p>;
  if (!data || !hotels) return <p className="loading">Loading reservations...</p>;
  if (showForm && !editReference) return <><div className="toolbar"><button className="btn" type="button" onClick={startCreate}>Add reservation</button></div><ReservationCreateView form={form} hotels={hotels} selectedHotel={selectedHotel} selectedRoom={selectedRoom} plans={plans} quote={quote} busy={busy} formError={formError} onChange={updateForm} onCheckAvailability={() => void checkAvailability()} onSubmit={submit} onClose={() => { setShowForm(false); setQuote(null); }} /></>;
  return <><div className="toolbar"><button className="btn" type="button" onClick={startCreate}>Add reservation</button></div>{showForm && <form className="formCard reservationForm" onSubmit={submit}><div className="rangeSectionHeader"><h2>{editReference ? `Edit ${editReference}` : 'Add reservation'}</h2><button className="smallBtn" type="button" onClick={() => setShowForm(false)}>Close</button></div><h3>Guest details</h3><div className="two"><label>Guest name<input value={form.guestName} onChange={(e) => setForm({ ...form, guestName: e.target.value })} required /></label><label>Email<input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required /></label></div><div className="two"><label>Mobile<input value={form.mobile} onChange={(e) => setForm({ ...form, mobile: e.target.value })} required /></label><label>GSTIN<input value={form.gstin} onChange={(e) => setForm({ ...form, gstin: e.target.value })} /></label></div><label>Address<textarea rows={2} value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} /></label><h3>Booking details</h3><div className="two"><label>Source<select value={form.source} onChange={(e) => setForm({ ...form, source: e.target.value, sourceName: '' })}><option>DIRECT</option><option>WEBSITE</option><option>PHONE</option><option>EMAIL</option><option>WHATSAPP</option><option>WALK_IN</option><option>AGENT</option><option>COMPANY</option><option>OTA</option></select></label>{['AGENT', 'COMPANY', 'OTA'].includes(form.source) && <label>{form.source === 'AGENT' ? 'Agent name' : form.source === 'COMPANY' ? 'Company name' : 'OTA name'}<input value={form.sourceName} onChange={(e) => setForm({ ...form, sourceName: e.target.value })} required /></label>}</div>{!editReference && <><div className="two"><label>Hotel<select value={form.hotelId} onChange={(e) => setForm({ ...form, hotelId: e.target.value, roomTypeId: '', ratePlanId: '' })} required><option value="">Select hotel</option>{hotels.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Room<select value={form.roomTypeId} onChange={(e) => setForm({ ...form, roomTypeId: e.target.value, ratePlanId: '' })} required><option value="">Select room</option>{selectedHotel?.rooms.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><div className="two"><label>Rate plan<select value={form.ratePlanId} onChange={(e) => setForm({ ...form, ratePlanId: e.target.value })} required><option value="">Select rate plan</option>{plans.map((item) => <option key={item.id} value={item.id}>{item.name} - {item.mealPlan}</option>)}</select></label><label>Check-in<input type="date" value={form.checkIn} onChange={(e) => setForm({ ...form, checkIn: e.target.value })} onInput={(e) => { const value = e.currentTarget.value; setForm((current) => ({ ...current, checkIn: value })); }} required /></label></div><div className="three"><label>Check-out<input type="date" value={form.checkOut} onChange={(e) => setForm({ ...form, checkOut: e.target.value })} onInput={(e) => { const value = e.currentTarget.value; setForm((current) => ({ ...current, checkOut: value })); }} required /></label><label>Rooms<input type="number" min="1" value={form.rooms} onChange={(e) => setForm({ ...form, rooms: Number(e.target.value) })} /></label><label>Adults<input type="number" min="1" value={form.adults} onChange={(e) => setForm({ ...form, adults: Number(e.target.value) })} /></label></div><label>Children<input type="number" min="0" value={form.children} onChange={(e) => setForm({ ...form, children: Number(e.target.value) })} /></label><section className="reservationCreateSummary" aria-label="Reservation summary"><h3>Reservation summary</h3><div><span>Hotel / room</span><b>{selectedHotel?.name || 'Select a hotel'} / {selectedRoom?.name || 'Select a room'}</b></div><div><span>Rate plan</span><b>{plans.find((item) => item.id === form.ratePlanId)?.name || 'Select a rate plan'}</b></div><div><span>Stay</span><b>{form.checkIn || 'Check-in'} to {form.checkOut || 'check-out'} · {form.rooms} room(s) · {form.adults} adult(s) · {form.children} child(ren)</b></div></section></>}{editReference && detail && <><div className="two"><label>Check-in<input type="date" value={form.checkIn} readOnly /></label><label>Check-out<input type="date" value={form.checkOut} readOnly /></label></div><div className="reviewGrid"><div><span>Hotel</span><b>{detail.hotel.name}</b></div><div><span>Rooms</span><b>{detail.lines.map((line) => `${line.roomType.name} / ${line.ratePlan.name}`).join(', ')}</b></div><div><span>Payment</span><b>{detail.paymentStatus}</b><small>Total INR {Number(detail.totalAmount).toFixed(2)}  -  Advance INR {Number(detail.advanceAmount).toFixed(2)}  -  Balance INR {Number(detail.balanceAmount).toFixed(2)}</small></div></div><ReservationPaymentSchedule schedule={detail.paymentSchedule} /></>}<h3>Instructions and requests</h3><details className="reservationAdvancedFields"><summary>Additional instructions (optional)</summary><label>Special request<textarea rows={2} value={form.specialRequest} onChange={(e) => setForm({ ...form, specialRequest: e.target.value })} /></label><label>Billing instructions<textarea rows={2} value={form.billingInstruction} onChange={(e) => setForm({ ...form, billingInstruction: e.target.value })} /></label><label>Internal remark<textarea rows={2} value={form.internalRemark} onChange={(e) => setForm({ ...form, internalRemark: e.target.value })} /></label></details>{editReference && <p className="mutedText">Stay dates, room/rate selection, tariff, and payments are shown from the reservation snapshot. Use the payment and cancellation workflows for those operational changes.</p>}{formError && <p className="error">{formError}</p>}<button className="btn" disabled={busy}>{busy ? 'Saving...' : editReference ? 'Save changes' : 'Create reservation'}</button></form>}<section className="panel"><p>{data.pagination.total} reservation(s)</p><table><thead><tr><th>Reference</th><th>Guest</th><th>Stay</th><th>Source</th><th>Status</th><th>Balance</th><th>Actions</th></tr></thead><tbody>{data.items.map((row) => <tr key={row.reference}><td><b>{row.reference}</b></td><td>{row.guestName}</td><td>{row.checkIn.slice(0, 10)} - {row.checkOut.slice(0, 10)}</td><td>{row.source}</td><td><span className={`status ${row.status === 'CONFIRMED' ? 'ok' : 'warn'}`}>{row.status}</span></td><td>INR {Number(row.balanceAmount).toFixed(2)}</td><td><div className="tableActionGroup"><button className="smallBtn" type="button" disabled={busy} onClick={() => void startEdit(row)}>Edit</button>{row.status !== 'CANCELLED' && <button className="smallBtn dangerBtn" type="button" disabled={busy} onClick={() => void cancel(row)}>Cancel</button>}</div></td></tr>)}</tbody></table></section></>;
}

export function ReservationToolbar() {
  const router = useRouter(); const pathname = usePathname(); const params = useSearchParams();
  function update(key: string, value: string) { const next = new URLSearchParams(params.toString()); if (value) next.set(key, value); else next.delete(key); next.delete('page'); router.replace(`${pathname}?${next.toString()}`, { scroll: false }); }
  return <section className="reservationToolbar panel" aria-label="Reservation filters"><div className="reservationToolbarSearch"><label htmlFor="reservation-list-search">Search reservations</label><input id="reservation-list-search" type="search" placeholder="Booking reference, guest, mobile or email" defaultValue={params.get('search') ?? ''} onChange={(event) => { const value = event.target.value; window.clearTimeout((event.currentTarget as HTMLInputElement & { searchTimer?: number }).searchTimer); (event.currentTarget as HTMLInputElement & { searchTimer?: number }).searchTimer = window.setTimeout(() => update('search', value), 250); }} onKeyDown={(event) => { if (event.key === 'Enter') update('search', event.currentTarget.value); if (event.key === 'Escape') { event.currentTarget.value = ''; update('search', ''); } }} /></div><label>Status<select aria-label="Reservation status filter" value={params.get('status') ?? ''} onChange={(event) => update('status', event.target.value)}><option value="">All statuses</option><option value="TENTATIVE">Tentative</option><option value="CONFIRMED">Confirmed</option><option value="PENDING_PAYMENT">Pending payment</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select></label><label>Arrival from<input type="date" value={params.get('from') ?? ''} onChange={(event) => update('from', event.target.value)} /></label><label>Arrival to<input type="date" value={params.get('to') ?? ''} min={params.get('from') ?? undefined} onChange={(event) => update('to', event.target.value)} /></label><p className="mutedText">Server-side filters · page size 25</p></section>;
}

export function ReservationPagination() {
  const router = useRouter(); const pathname = usePathname(); const params = useSearchParams(); const [state, setState] = useState<{ page: number; pages: number; total: number } | null>(null); const [error, setError] = useState('');
  const page = Math.max(1, Number(params.get('page') ?? 1) || 1); const query = new URLSearchParams({ page: String(page), limit: '25' }); if (params.get('search')) query.set('search', params.get('search')!); if (params.get('status')) query.set('status', params.get('status')!); if (params.get('hotelId')) query.set('hotelId', params.get('hotelId')!); if (params.get('from')) query.set('from', params.get('from')!); if (params.get('to')) query.set('to', params.get('to')!);
  useEffect(() => { let cancelled = false; setError(''); apiRequest<ReservationList>(`/reservations?${query.toString()}`).then((body) => { if (!cancelled) setState({ page: body.pagination.page, pages: body.pagination.pages, total: body.pagination.total }); }).catch((reason) => { if (!cancelled) setError(reason instanceof Error ? reason.message : 'Could not load reservation pagination'); }); return () => { cancelled = true; }; }, [query.toString()]);
  function go(nextPage: number) { const next = new URLSearchParams(params.toString()); if (nextPage > 1) next.set('page', String(nextPage)); else next.delete('page'); router.replace(`${pathname}?${next.toString()}`, { scroll: false }); }
  if (error) return <p className="error" role="alert">{error}</p>; if (!state) return <p className="loading" role="status">Loading reservation page…</p>;
  return <nav className="reservationPagination" aria-label="Reservation pagination"><span>{state.total} result{state.total === 1 ? '' : 's'}</span><button className="smallBtn secondary" type="button" disabled={page <= 1} onClick={() => go(page - 1)}>Previous</button><strong>Page {state.page} of {Math.max(1, state.pages)}</strong><button className="smallBtn secondary" type="button" disabled={page >= state.pages} onClick={() => go(page + 1)}>Next</button></nav>;
}

